rule.definition:
a!localVariables(
  local!orgid: ri!orgid,

  /* Get org data */
  local!orgdata: if(
    a!isNotNullOrEmpty(local!orgid),
    #"_a-0000eeda-0177-8000-9e52-011c48011c48_1084584"(orgId: local!orgid),
    null()
  ),

  /* Get org manager */
  local!orgmanager: if(
    a!isNotNullOrEmpty(local!orgdata),
    index(
      local!orgdata,
      #"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2",
      null()
    ),
    null()
  ),

  /* Get parent org hierarchy data */
  local!orgparentdata: if(
    a!isNotNullOrEmpty(local!orgid),
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1092772"(suborgaid: local!orgid, isActive: true()),
    null()
  ),

  /* Get parent org ID */
  local!orgparentid: if(
    a!isNotNullOrEmpty(local!orgparentdata),
    index(
      local!orgparentdata,
      #"urn:appian:record-field:v1:28808922-2be4-47a6-a7b6-33b1b5da8c2d/8bd8d3b2-2d84-4bf1-baec-7d111de875eb",
      null()
    ),
    null()
  ),

  /* Get parent org data */
  local!parentorgdata: if(
    a!isNotNullOrEmpty(local!orgparentid),
    #"_a-0000eeda-0177-8000-9e52-011c48011c48_1084584"(orgId: local!orgparentid),
    null()
  ),

  /* Get parent org manager */
  local!parentorgmanager: if(
    a!isNotNullOrEmpty(local!parentorgdata),
    index(
      local!parentorgdata,
      #"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2",
      null()
    ),
    null()
  ),
  local!isSystemgroup:#"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
    username: loggedInUser(),
    groups: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1189961"
  ),

  /* Check if logged in user is org manager or parent org manager */
  local!ra: or(
    and(
      a!isNotNullOrEmpty(local!parentorgmanager),
      loggedInUser() = touser(local!parentorgmanager)
    ),
    and(
      a!isNotNullOrEmpty(local!orgmanager),
      loggedInUser() = touser(local!orgmanager)
    ),
    local!isSystemgroup
  ),

  local!ra
)
